def bounded_batches(items, max_rows):
    if max_rows <= 0:
        raise ValueError("max_rows must be positive")

    batches = []
    current_batch = []
    current_total = 0

    for item in items:
        row_count = item[1]

        if row_count > max_rows:
            if current_batch:
                batches.append(current_batch)
                current_batch = []
                current_total = 0
            batches.append([item])
        elif current_total + row_count > max_rows:
            if current_batch:
                batches.append(current_batch)
                current_batch = []
                current_total = 0
            current_batch.append(item)
            current_total = row_count
        else:
            current_batch.append(item)
            current_total += row_count

    if current_batch:
        batches.append(current_batch)

    return batches
